-- PIP mobility awards by council, 202507 and 202607: 678 rows (England and Wales; 21 counties summed from their districts)
-- written by scripts/import-pip-mobility.js --sql
\set ON_ERROR_STOP on
BEGIN;
CREATE TABLE public.council_pip_mobility_backup_20261021 AS SELECT * FROM public.council_pip_mobility WHERE period IN ('2025-07-01', '2026-07-01');
ALTER TABLE public.council_pip_mobility_backup_20261021 ENABLE ROW LEVEL SECURITY;  -- service role only (already on: new tables here get RLS automatically)
DELETE FROM public.council_pip_mobility WHERE period IN ('2025-07-01', '2026-07-01');
DO $$ DECLARE n int; bad int; BEGIN
  SELECT count(*) INTO n FROM public.council_pip_mobility WHERE period IN ('2025-07-01', '2026-07-01');
  IF n <> 678 THEN RAISE EXCEPTION 'expected 678 rows, found %', n; END IF;
  SELECT count(*) INTO n FROM public.council_pip_mobility p JOIN public.councils c ON c.gss_code = p.gss WHERE p.period IN ('2025-07-01', '2026-07-01');
  IF n <> 678 THEN RAISE EXCEPTION 'only % rows match a council', n; END IF;
  -- every county row equals its districts added up, from the stored rows
  SELECT count(*) INTO bad FROM public.council_pip_mobility p
   CROSS JOIN LATERAL (SELECT sum(d.enhanced)::int AS e, sum(d.standard)::int AS s, sum(d.nil)::int AS n, count(*) AS k FROM public.council_pip_mobility d
          WHERE d.period = p.period AND d.gss = ANY (p.district_gss) AND NOT d.derived_from_districts) t
   WHERE p.derived_from_districts AND p.period IN ('2025-07-01', '2026-07-01')
     AND ((p.enhanced, p.standard, p.nil) IS DISTINCT FROM (t.e, t.s, t.n) OR t.k <> cardinality(p.district_gss));
  IF bad > 0 THEN RAISE EXCEPTION '% county rows do not equal their districts', bad; END IF;
  RAISE NOTICE 'loaded % rows', 678;
END $$;
COMMIT;
